import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line != null) { int x = Integer.parseInt(line.trim()); if (x >= 12) { System.out.println("Yes"); } else { System.out.println("No"); } } } }